// Must be "default" or match ^[a-z0-9-]+$
func ValidateContextName(name string) error {
	if name == "default" {
		return nil
	}

	// Pattern: lowercase letters, digits, hyphens
	matched, err := regexp.MatchString("^[a-z0-9-]+$", name)
	if err != nil {
