func isCtxExists(err error) bool {
	for e := err; e != nil; {
		if e == ErrContextExists {
			return true
		}
		u, ok := e.(interface{ Unwrap() error })
		if !ok {
			return false
		}
		e = u.Unwrap()
	}
	return false
}

